use system.gpu
use system.gpu.atomic
use system.collections.array
use system.collections.list
use system.fs
use system.io
use system.math
use system.os

// Tally slots, in the GPU buffer `tally`:
//   0       inside points
//   1       sum of escape times over escaped points
//   2       count of escaped points
//   3 .. 10 escaped points per bin, bin b at slot 3 + b
const SLOTS = 11

fn pad3(n int) String
    if n < 10: return f"00{n}"
    if n < 100: return f"0{n}"
    return f"{n}"

fn main() int
    let args = Args()
    if args.length() < 1
        panic("usage: main <input-file>")

    let fs = Fs()
    let text = match fs.read_file(args.element_at(0))
        Result.Ok(s): s
        Result.Err(_): panic("cannot read input file")

    let tokens = List<String>()
    for part in text.replace("\r", " ").replace("\n", " ").replace("\t", " ").split(" ")
        if not part.is_empty()
            tokens.push(part)
    if tokens.length() < 7
        panic("input needs 3 integers and 4 decimals")

    let width = tokens.element_at(0).to_int() ?? panic("bad width")
    let height = tokens.element_at(1).to_int() ?? panic("bad height")
    let limit = tokens.element_at(2).to_int() ?? panic("bad limit")
    let x_min = tokens.element_at(3).to_float() ?? panic("bad x_min")
    let x_max = tokens.element_at(4).to_float() ?? panic("bad x_max")
    let y_min = tokens.element_at(5).to_float() ?? panic("bad y_min")
    let y_max = tokens.element_at(6).to_float() ?? panic("bad y_max")

    let total = width * height
    let x0 = x_min as f32
    let y0 = y_min as f32
    let dx = ((x_max - x_min) / (width as float)) as f32
    let dy = ((y_max - y_min) / (height as float)) as f32
    let max_steps = limit

    gpu var tally = Array<Atomic<i32>, SLOTS>()
    gpu var out = Array<i32, SLOTS>()

    // One GPU thread per grid point. Each thread runs the escape loop for its
    // point and adds its result to the tally with atomic adds.
    forall idx in 0..total
        let i = idx % width
        let j = idx / width
        let cx = x0 + ((i as f32) + 0.5) * dx
        let cy = y0 + ((j as f32) + 0.5) * dy
        var zx f32 = 0.0
        var zy f32 = 0.0
        var n = 0
        while n < max_steps and zx * zx + zy * zy <= 4.0
            let next_zx = zx * zx - zy * zy + cx
            zy = 2.0 * zx * zy + cy
            zx = next_zx
            n = n + 1
        if n == max_steps
            atomic_add(tally, 0, 1)
        else
            atomic_add(tally, 1, n)
            atomic_add(tally, 2, 1)
            atomic_add(tally, 3 + (8 * n) / max_steps, 1)

    // Copy the tally out of the atomic buffer into a plain buffer the host can read.
    forall s in 0..SLOTS
        out[s] = atomic_add(tally, s, 0) as i32

    let inside = out.element_at(0)
    let escaped = out.element_at(2)
    let mut_sum = out.element_at(1)

    println(f"INSIDE {inside}")
    for b in 0..8
        println(f"BIN {b} {out.element_at(3 + b)}")

    // MEAN is written with three digits after the point; computed in integer
    // thousandths so no float formatting is needed.
    var milli = 0
    if escaped > 0
        milli = round((mut_sum as float) * 1000.0 / (escaped as float)) as int
    let whole = milli / 1000
    let frac = milli % 1000
    println(f"MEAN {whole}.{pad3(frac)}")
    return 0

